export const BODY: string = "\n<p>PNG اسکرین شاٹ اسی تصویر کی JPG سے دس گنا زیادہ بھاری ہو سکتا ہے۔ اسے بدلنے میں ایک منٹ سے کم لگتا ہے، اور نتیجہ بھیجنا، اپ لوڈ کرنا اور محفوظ کرنا کہیں آسان ہو جاتا ہے۔</p>\n<p>صرف مشکل حصہ شفافیت ہے۔ JPG شفاف پکسل محفوظ نہیں کر سکتا، اس لیے بدلنے سے پہلے ان کے لیے بھرنے والا رنگ چننا ہوتا ہے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، تاکہ آپ کی پہلی تبدیلی صاف نکلے۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: شفافیت جانچیں</h2>\n<p>PNG کھولیں اور اس کا پس منظر دیکھیں۔ تصویر یا اسکرین شاٹ میں شفافیت نہیں ہوتی، اس لیے آپ بھرنے والے رنگ کے بارے میں سوچے بغیر بدل سکتے ہیں۔</p>\n<p>لوگو، آئیکن یا مصنوعات کی کٹ آؤٹ میں شاید شفافیت ہو۔ شفاف حصوں کو میٹ رنگ چاہیے ہوگا، اور آپ کو شروع کرنے سے پہلے طے کرنا چاہیے کہ کون سا۔</p>\n<p>سفید زیادہ تر منزلوں کو سوٹ کرتا ہے۔ دستاویزات، ویب صفحے اور فارم عام طور پر سفید پر بیٹھتے ہیں، اس لیے سفید میٹ وہاں قدرتی لگتا ہے۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: PNG سے JPG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/png-ko-jpg-mein-convert-karein/\">PNG to JPG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے، بغیر کچھ انسٹال کیے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ، میٹ رنگ چننے والا اور کوالٹی سلائیڈر دکھائی دے گا۔ یہ تین کنٹرول ہی پورا کام ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو نجی ڈیش بورڈ اور دستاویزات کے اسکرین شاٹ کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی PNG فائلیں اپ لوڈ کریں</h2>\n<p>اپنی PNG فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>ہر فائل کارڈ کے طور پر دکھائی دیتی ہے، تھمب نیل، ابعاد اور سائز کے ساتھ۔ فوری نظر سے یقین ہو جاتا ہے کہ درست فائلیں لوڈ ہوئیں اور کوئی اضافی نہیں آئی۔</p>\n<p>آپ Ctrl+V سے کلپ بورڈ سے اسکرین شاٹ سیدھا پیسٹ بھی کر سکتے ہیں۔ یہ ابھی لیا گیا اسکرین شاٹ بدلنے کا تیز ترین طریقہ ہے۔</p>\n<h2 id=\"step-3-matte-colour\">مرحلہ 3: میٹ رنگ چنیں</h2>\n<p>شفاف حصوں کے بھرنے کے لیے میٹ رنگ چننے والے پر کلک کریں۔ سفید پہلے سے طے شدہ ہے اور زیادہ تر استعمال کو سوٹ کرتا ہے۔</p>\n<p>اگر تصویر گہرے پس منظر پر بیٹھے گی تو گہرا چارکول چنیں، یا کسی مخصوص ویب سائٹ برانڈ رنگ سے بالکل ملانے کے لیے ہیکس کوڈ لکھیں۔</p>\n<p>اگر آپ کی PNG میں شفافیت نہیں ہے تو یہ ترتیب کچھ نہیں کرتی۔ تصویریں اور اسکرین شاٹ جو بھی رنگ چنیں، ویسے ہی گزر جاتے ہیں۔</p>\n<h2 id=\"step-4-quality\">مرحلہ 4: کوالٹی سلائیڈر طے کریں</h2>\n<p>کوالٹی سلائیڈر 20 سے 100 فیصد تک چلتا ہے۔ متن والے اسکرین شاٹ کے لیے 85 سے 90 فیصد حروف صاف رکھتا ہے۔</p>\n<p>PNG کے طور پر محفوظ تصویروں کے لیے 80 سے 85 فیصد بہترین نقطہ ہے۔ تصویر صاف لگتی ہے، اور فائل ڈرامائی طور پر چھوٹی ہو جاتی ہے۔</p>\n<p>کوالٹی صرف اس وقت کم کریں جب سائز حد مجبور کرے۔ 90 سے 80 فیصد پر جانا اکثر فائل سائز آدھا کر دیتا ہے، بغیر نظر آنے والی تبدیلی کے۔</p>\n<h2 id=\"step-5-convert-preview\">مرحلہ 5: بدلیں اور نتیجہ کا پیش نظارہ دیکھیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ہر فائل الگ بدلتی ہے، اس لیے آپ پیش رفت کارڈ بہ کارڈ دیکھ سکتے ہیں۔</p>\n<p>ہر کارڈ پرانی PNG سائز کے ساتھ نیا JPG سائز دکھاتا ہے۔ اچھی تبدیلی اسکرین شاٹ کو اسی فیصد یا زیادہ چھوٹا کر دیتی ہے۔</p>\n<p>نتیجہ ساتھ ساتھ جانچنے کے لیے کسی کارڈ پر Compare پر کلک کریں۔ اسپلٹ ہینڈل تصویر پر گھسیٹیں اور متن، کنارے اور سائے زوم کر کے دیکھیں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: JPG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک JPG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .jpg ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی JPG ہو۔ ZIP نام بتاتا ہے کہ اس میں بدلی ہوئی فائلیں ہیں۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ JPG اپنے فوٹو ویور میں کھولیں، یقین کریں کہ وہ درست لگتی ہے اور وہاں کھلتی ہے جہاں اسے کھلنا ہے۔</p>\n<ol>\n<li>PNG سے JPG ٹول کھولیں اور اپنی PNG فائلیں اپ لوڈ کریں۔</li>\n<li>شفاف حصوں کے لیے میٹ رنگ چنیں۔</li>\n<li>کوالٹی سلائیڈر 85 فیصد یا اوپر پر طے کریں۔</li>\n<li>بدلیں، Compare سے پیش نظارہ دیکھیں، پھر JPG ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-screenshots\">اسکرین شاٹ درست طریقے سے بدلنا</h2>\n<p>اسکرین شاٹ سب سے عام PNG سے JPG کام ہیں۔ میک اور ونڈوز دونوں اسکرین شاٹ PNG کے طور پر محفوظ کرتے ہیں، اور وہ فائلیں ضرورت سے کہیں بڑی ہوتی ہیں۔</p>\n<p>تیز ترین ورک فلو کے لیے اسکرین شاٹ Ctrl+V سے سیدھا پیسٹ کریں۔ اسکرین شاٹ لیں، اسے کنورٹر میں پیسٹ کریں اور سیکنڈوں بعد JPG ڈاؤن لوڈ کریں۔</p>\n<p>اسکرین شاٹ کے لیے کوالٹی 85 فیصد یا اوپر پر رکھیں۔ مینیو، بٹن اور جسمانی متن سب کو اس کوالٹی کی ضرورت ہوتی ہے تاکہ پڑھنے کے قابل رہیں۔</p>\n<h2 id=\"converting-a-batch\">اسکرین شاٹ کا بیچ بدلنا</h2>\n<p>فائل پکر میں ایک ساتھ 25 اسکرین شاٹ چنیں۔ وہ سب قطار میں لوڈ ہو جاتے ہیں، اور ایک کلک سے سب بدل جاتے ہیں۔</p>\n<p>پورے بیچ کے لیے ایک ہی میٹ رنگ اور کوالٹی استعمال کریں۔ مستقل مزاجی اہم ہے جب اسکرین شاٹ ایک ہی دستاویز یا پریزنٹیشن سے تعلق رکھتے ہوں۔</p>\n<p>بیچ چلتے ہوئے غلطی والے بیج دیکھیں۔ ایک خراب فائل انتباہ دکھاتی ہے، باقی کو روکے بغیر، اس لیے اچھی فائلیں پھر بھی مکمل ہوتی ہیں۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر شفاف لوگو کو کالا ڈبہ مل جائے تو میٹ رنگ کالا تھا یا طے نہیں ہوا تھا۔ اسے سفید یا اپنے صفحے کے رنگ پر بدلیں اور دوبارہ بدلیں۔</p>\n<p>اگر متن دھندلا لگے تو کوالٹی بہت کم تھی۔ سلائیڈر 90 فیصد پر بڑھائیں اور اصل PNG سے دوبارہ بدلیں۔</p>\n<p>اگر JPG PNG سے بمشکل چھوٹی ہو تو تصویر شاید سادہ گرافک ہے۔ PNG فلیٹ رنگ پہلے سے اچھی کمپریس کرتا ہے، اس لیے تبدیلی سے کچھ نہیں بچتا۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے PNG چنیں۔ فون پر محفوظ اسکرین شاٹ ڈیسک ٹاپ والوں کی طرح بدلتے ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی PNG موبائل پروسیسر پر انکوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں دس فائلیں آرام دہ ہیں۔</p>\n<p>PNG سے JPG میں بدلی فائل آپ کے فون کے Downloads فولڈر میں محفوظ ہوتی ہے۔ آئی فون پر اسے Files ایپ میں دیکھیں، اینڈرائیڈ پر فائل مینیجر کھول کر تلاش کریں۔</p>\n<h2 id=\"mac-screenshots\">میک اسکرین شاٹ بدلنا</h2>\n<p>میک اسکرین شاٹ پہلے سے طے شدہ طور پر PNG میں محفوظ ہوتے ہیں، اور وہ بڑے ہوتے ہیں۔ ریٹنا اسکرین شاٹ 5 MB ہو سکتا ہے، جبکہ وہی تصویر JPG کے طور پر 500KB ہوتی ہے، بغیر نظر آنے والے فرق کے۔</p>\n<p>Shift، Command اور 4 سے اسکرین شاٹ لیں، پھر فائل کنورٹر میں گھسیٹ دیں۔ PNG سیکنڈوں میں JPG میں بدلتا ہے، اور نتیجہ شیئر کرنے کے لیے تیار ہوتا ہے۔</p>\n<p>میک اسکرین شاٹ کے لیے کوالٹی 85 فیصد یا اوپر پر رکھیں۔ ریٹنا متن صاف رہتا ہے، اور فائل اسی فیصد یا زیادہ چھوٹی ہو جاتی ہے۔</p>\n<h2 id=\"windows-screenshots\">ونڈوز اسکرین شاٹ بدلنا</h2>\n<p>ونڈوز اسکرین شاٹ بھی PNG میں محفوظ ہوتے ہیں، چاہے پرنٹ اسکرین سے لیے جائیں یا Snipping Tool سے۔ وہ فائلیں بڑی ہوتی ہیں، اور انہیں JPG میں بدلنے سے حقیقی جگہ بچتی ہے۔</p>\n<p>اسکرین شاٹ Ctrl+V سے کنورٹر میں سیدھا پیسٹ کریں۔ کلپ بورڈ تصویر فوراً لوڈ ہوتی ہے، اور JPG سیکنڈوں بعد ڈاؤن لوڈ ہوتی ہے، بغیر کسی فائل جھنجھٹ کے۔</p>\n<p>Snipping Tool کیپچر کے لیے پہلے اسنپ محفوظ کریں، پھر فائل بدلیں۔ اسنپ ٹول پہلے سے طے شدہ طور پر PNG محفوظ کرتا ہے، اور کنورٹر باقی سنبھال لیتا ہے۔</p>\n<h2 id=\"phone-screenshots\">فون اسکرین شاٹ بدلنا</h2>\n<p>فون اسکرین شاٹ آئی فون اور اینڈرائیڈ دونوں پر PNG میں محفوظ ہوتے ہیں، اور وہ جلد جمع ہو جاتے ہیں۔ سو اسکرین شاٹ والا فون صرف PNG فائلوں پر ایک گیگا بائٹ ضائع کر سکتا ہے۔</p>\n<p>جن اسکرین شاٹ کو رکھنا ہو، انہیں بدلیں اور باقی حذف کر دیں۔ زیادہ تر اسکرین شاٹ عارضی ہوتے ہیں، اور ان سب کو رکھنا بغیر فائدہ اسٹوریج ضائع کرتا ہے۔</p>\n<p>رکھنے والے اسکرین شاٹ، جیسے رسید یا تصدیق، کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ متن پڑھنے کے قابل رہتا ہے، اور فائل کہیں چھوٹی ہوتی ہے۔</p>\n<h2 id=\"design-mockups\">ڈیزائن موک اپ بدلنا</h2>\n<p>ڈیزائن موک اپ اکثر PNG کے طور پر برآمد ہوتے ہیں، کیونکہ یہ فارمیٹ متن اور شکلیں تیز رکھتا ہے۔ وہ فائلیں بڑی ہوتی ہیں، اور انہیں JPG میں بدلنے سے کلائنٹ کے ساتھ شیئر کرنا آسان ہو جاتا ہے۔</p>\n<p>جائزے کے لیے کلائنٹ جانے والے موک اپ کے لیے 90 فیصد کوالٹی پر JPG میں بدلیں۔ ڈیزائن صاف رہتا ہے، فائل آسانی سے ای میل ہوتی ہے اور کلائنٹ اسے کہیں بھی کھول سکتا ہے۔</p>\n<p>جس موک اپ پر کلائنٹ تشریح کرے گا، اس کے لیے PNG رکھیں۔ بغیر نقصان والا فارمیٹ تشریح کے مرحلوں سے گزر کر بچ جاتا ہے، جبکہ JPG ہر محفوظ کرنے پر نرم ہوتی ہے۔</p>\n<h2 id=\"images-for-presentation\">پریزنٹیشن کے لیے تصویریں بدلنا</h2>\n<p>پریزنٹیشن تصویروں کو تیز اور معقول سائز کا ہونا چاہیے۔ سلائیڈ میں PNG اسکرین شاٹ صاف لگتا ہے، جبکہ JPG تصویر ڈیک کو بہت بڑا ہونے سے بچاتی ہے۔</p>\n<p>سلائیڈ کے لیے اسکرین شاٹ کو 90 فیصد کوالٹی پر JPG میں بدلیں۔ متن پروجیکٹر پر پڑھنے کے قابل رہتا ہے، اور فائل ڈیک کو قابل انتظام رکھنے کے لیے کافی چھوٹی ہوتی ہے۔</p>\n<p>سلائیڈ پر مکمل اسکرین تصویر کے لیے 85 فیصد پر JPG درست انتخاب ہے۔ تصویر صاف لگتی ہے، سلائیڈ تیزی سے کھلتی ہے اور سامعین تصویر دیکھتے ہیں، پکسل نہیں۔</p>\n<h2 id=\"images-for-whatsapp-group\">واٹس ایپ گروپ کے لیے تصویریں بدلنا</h2>\n<p>واٹس ایپ تصویریں خود بخود کمپریس کرتا ہے، اس لیے گروپ کو بھیجی گئی PNG اسکرین شاٹ ویسے بھی چھوٹی JPG کے طور پر پہنچتی ہے۔ پہلے خود بدلنے سے کوالٹی پر آپ کا کنٹرول رہتا ہے۔</p>\n<p>بھیجنے سے پہلے اسکرین شاٹ کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ متن پڑھنے کے قابل رہتا ہے، فائل تیزی سے بھیجی جاتی ہے اور واٹس ایپ کی کمپریشن کو اچھا شروعاتی نقطہ ملتا ہے۔</p>\n<p>تیز رہنے والی تصویر، جیسے ادائیگی کی تصدیق، کے لیے اسے دستاویز کے طور پر بھیجیں۔ دستاویز منسلکہ واٹس ایپ کی کمپریشن مکمل چھوڑ دیتا ہے۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، میٹ چنیں، کوالٹی طے کریں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/png-ko-jpg-rehnumai/\">PNG to JPG: Complete Guide</a> پڑھیں، اور سائز سمجھوتوں کے لیے <a href=\"/ur/blog/png-ko-jpg-file-size-aur-quality/\">PNG to JPG: File-Size Savings and Quality Trade-offs</a> دیکھیں۔ اگر منزل ویب سائٹ ہے تو <a href=\"/ur/png-ko-webp-mein-convert-karein/\">PNG to WebP کنورٹر</a> شفافیت رکھتے ہوئے فائل چھوٹی کرتا ہے۔</p>\n";

